import django_rq
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework import status
from .models import WebhookEndpoint

class WebhookJobRetryView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        job_id = request.data.get('job_id')
        failed_queue = django_rq.get_failed_queue()
        job = failed_queue.fetch_job(job_id)
        if not job:
            return Response({'error': 'Failed job not found'}, status=status.HTTP_404_NOT_FOUND)

        # Ensure the webhook endpoint referenced in the job belongs to request.user.organization
        endpoint_id = job.kwargs.get('endpoint_id')
        if not WebhookEndpoint.objects.filter(id=endpoint_id, organization=request.user.organization).exists():
            return Response({'error': 'Access denied to this webhook job'}, status=status.HTTP_403_FORBIDDEN)

        failed_queue.requeue(job_id)
        return Response({'status': 'requeued', 'job_id': job_id})
